input.new_string:
import { describe, expect, test } from "bun:test";
import { greet, greetAll, add } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("greetAll returns combined greeting for multiple names", () => {
    expect(greetAll(["Alice", "Bob"])).toBe("Hello, Alice! Hello, Bob!");
  });

  test("greetAll returns single greeting for one name", () => {
    expect(greetAll(["Alice"])).toBe("Hello, Alice!");
  });

  test("greetAll returns empty string for empty array", () => {
    expect(greetAll([])).toBe("");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

